  "Rechercher par nom, entreprise ou ville": { en: "Search by name, company or city", es: "Buscar por nombre, empresa o ciudad", de: "Nach Name, Unternehmen oder Stadt suchen", it: "Cerca per nome, azienda o città", pt: "Pesquisar por nome, empresa ou cidade" },
